create table if not exists public.discovery_sources (id uuid primary key default gen_random_uuid(), key text not null unique, name text not null, base_url text, source_type text not null default 'web', enabled boolean not null default true, policy_mode text not null default 'public_only', config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.discovery_runs (id uuid primary key default gen_random_uuid(), source_id uuid references public.discovery_sources(id) on delete set null, status text not null default 'queued', query text, city text not null default 'Sadat City', country text not null default 'Egypt', started_at timestamptz, finished_at timestamptz, stats jsonb not null default '{}'::jsonb, error_message text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.discovery_evidence (id uuid primary key default gen_random_uuid(), run_id uuid not null references public.discovery_runs(id) on delete cascade, source_id uuid references public.discovery_sources(id) on delete set null, url text not null, canonical_url text, title text, captured_at timestamptz not null default now(), content_hash text, raw_data jsonb not null default '{}'::jsonb, extraction jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(run_id, url));
create table if not exists public.discovery_entities (id uuid primary key default gen_random_uuid(), run_id uuid references public.discovery_runs(id) on delete set null, evidence_id uuid references public.discovery_evidence(id) on delete set null, entity_type text not null, external_key text, name text, phone text, email text, address text, city text, source_url text, confidence numeric(5,4) not null default 0, status text not null default 'candidate', attributes jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.discovery_jobs (id uuid primary key default gen_random_uuid(), run_id uuid references public.discovery_runs(id) on delete cascade, job_type text not null, payload jsonb not null default '{}'::jsonb, status text not null default 'queued', priority integer not null default 100, attempts integer not null default 0, max_attempts integer not null default 5, locked_by text, locked_at timestamptz, available_at timestamptz not null default now(), last_error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists discovery_runs_status_idx on public.discovery_runs(status, created_at desc);
create index if not exists discovery_evidence_url_idx on public.discovery_evidence(canonical_url);
create index if not exists discovery_entities_type_status_idx on public.discovery_entities(entity_type, status, created_at desc);
create index if not exists discovery_entities_phone_idx on public.discovery_entities(phone) where phone is not null;
create index if not exists discovery_jobs_claim_idx on public.discovery_jobs(status, available_at, priority desc, created_at);
create unique index if not exists discovery_entities_external_key_uq on public.discovery_entities(entity_type, external_key) where external_key is not null;
